import json, random, sys
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/work')
from utils import run_request
from ref import Ref
from fuzz import gen_borders


def gen_run(rng, ops, big):
    M = rng.randint(1, 16 if big else 6)
    L = rng.randint(1, 8 if big else 3)
    U = rng.choice([1, 3, 7, 33, 500, 2000000000]) if big else rng.choice([1, 3, 7, 33])
    fifo_bytes = rng.choice([1, 5, 50, 1000, 2147483647])
    pifo_bytes = rng.choice([1, 5, 50, 1000, 2147483647])
    refill_batch = rng.choice([1, 2, 32])
    sample_period = rng.choice([1, 2, 7, 100000])
    borders = gen_borders(rng, U, max_ranges=10)
    kind = rng.choice(["fifo", "sp", "sff", "wfq"])
    flows = list(range(rng.randint(1, 8)))
    if kind == "sp":
        policy = {"kind": "sp", "levels": [[f, rng.randint(0, min(U, 1000))] for f in flows]}
    elif kind == "wfq":
        policy = {"kind": "wfq", "weights": [[f, rng.randint(1, 1024)] for f in flows]}
    else:
        policy = {"kind": kind}
    events = []
    ids = 0
    saved = []
    for _ in range(ops):
        c = rng.random()
        if c < 0.42:
            ids += 1
            events.append(["enqueue", ids, rng.choice(flows),
                           rng.randint(1, 1000000), rng.randint(0, 2147483647)])
        elif c < 0.62:
            events.append(["dequeue", rng.randint(1, 8)])
        elif c < 0.68:
            events.append(["sample"])
        elif c < 0.74:
            events.append(["repartition", gen_borders(rng, U, max_ranges=10)])
        elif c < 0.82:
            pick = rng.randint(1, ids) if ids and rng.random() < 0.85 else 999999
            events.append(["cancel", pick])
        elif c < 0.88:
            pick = rng.randint(1, ids) if ids and rng.random() < 0.85 else 999999
            events.append(["inspect", pick])
        elif c < 0.92 and kind == "wfq":
            events.append(["weight", rng.choice(flows), rng.randint(1, 1024)])
        elif c < 0.96:
            name = rng.randint(0, 5)
            events.append(["save", name])
            if name not in saved:
                saved.append(name)
        else:
            if saved:
                events.append(["restore", rng.choice(saved)])
            else:
                events.append(["sample"])
    return {"banks": M, "load_balancers": L, "fifo_bytes": fifo_bytes,
            "pifo_bytes": pifo_bytes, "refill_batch": refill_batch,
            "sample_period": sample_period, "borders": borders,
            "policy": policy, "events": events}


def one(seed):
    rng = random.Random(seed)
    big = seed % 3 == 0
    runs = [gen_run(rng, ops=rng.randint(1, 120), big=big) for _ in range(rng.randint(1, 3))]
    req = {"runs": runs}
    got = run_request(req)
    exp_runs = []
    for cfg in runs:
        ref = Ref(cfg)
        log = ref.run(cfg["events"])
        exp_runs.append({"log": log, "state": ref.certificate()})
    exp = {"runs": exp_runs}
    if json.loads(json.dumps(got)) != exp:
        return runs, got, exp
    return None


def main():
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 500
    base = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    fails = 0
    for seed in range(base, base + n):
        res = one(seed)
        if res:
            fails += 1
            runs, got, exp = res
            print("FAIL seed", seed)
            if fails == 1:
                for ri, (g, e) in enumerate(zip(got["runs"], exp["runs"])):
                    if g["log"] != e["log"]:
                        for a, b in zip(g["log"], e["log"]):
                            if a != b:
                                print("run", ri, "got:", json.dumps(a))
                                print("run", ri, "exp:", json.dumps(b))
                                break
                        break
                    if g["state"] != e["state"]:
                        print("run", ri, "state got:", json.dumps(g["state"]))
                        print("run", ri, "state exp:", json.dumps(e["state"]))
                        break
                print(json.dumps(runs[0]["policy"]), runs[0]["borders"])
            if fails >= 3:
                break
    print(f"done {n} seeds, {fails} failures")


if __name__ == "__main__":
    main()
